shellCommands.command:
/bin/bash -c "apply_patch <<'PATCH'
*** Begin Patch
*** Add File: app/globals.css
+@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
+
+:root {
+  color-scheme: light;
+  --ink: #20242f;
+  --muted: #828796;
+  --line: #eaebf0;
+  --purple: #6658df;
+  --purple-dark: #5144c4;
+  --surface: #fff;
+  --canvas: #f8f9fc;
+}
+
+* { box-sizing: border-box; }
+
+html, body { min-height: 100%; }
+
+body {
+  margin: 0;
+  background: var(--canvas);
+  color: var(--ink);
+  font-family: 'DM Sans', sans-serif;
+  font-size: 14px;
+  -webkit-font-smoothing: antialiased;
+}
+
+button, input { font: inherit; }
+button { cursor: pointer; }
+
+.app-shell { min-height: 100vh; }
+
+.sidebar {
+  position: fixed;
+  inset: 0 auto 0 0;
+  z-index: 2;
+  display: flex;
+  width: 250px;
+  flex-direction: column;
+  border-right: 1px solid #e9eaf0;
+  background: #fff;
+  padding: 27px 17px 17px;
+}
+
+.brand {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 0 9px;
+  color: #292c38;
+  font-family: Manrope, sans-serif;
+  font-size: 18px;
+  font-weight: 800;
+  letter-spacing: -1px;
+  text-decoration: none;
+}
+
+.brand-mark {
+  display: grid;
+  width: 30px;
+  height: 30px;
+  place-items: center;
+  border-radius: 9px;
+  background: linear-gradient(145deg, #8174f0, #584acb);
+  box-shadow: 0 4px 8px #6557db36;
+  color: #fff;
+  font-family: Manrope, sans-serif;
+  font-size: 17px;
+  font-weight: 800;
+  letter-spacing: -1px;
+}
+
+.brand-admin { margin-left: 8px; color: #9699a5; font-family: 'DM Sans', sans-serif; font-size: 8px; font-weight: 700; letter-spacing: 1.25px; }
+.workspace-label { margin: 49px 10px 12px; color: #a1a4af; font-size: 10px; font-weight: 700; letter-spacing: 1.1px; }
+.navigation { display: grid; gap: 5px; }
+
+.nav-link {
+  display: flex;
+  height: 42px;
+  align-items: center;
+  gap: 12px;
+  border-radius: 8px;
+  padding: 0 12px;
+  color: #6e7280;
+  font-size: 13px;
+  font-weight: 500;
+  text-decoration: none;
+  transition: background .15s ease, color .15s ease;
+}
+
+.nav-link:hover { background: #f7f6ff; color: var(--purple); }
+.nav-link.active { background: #f1efff; color: #574acb; font-weight: 600; }
+.nav-icon { width: 17px; color: #9396a2; font-size: 18px; line-height: 1; text-align: center; }
+.active .nav-icon { color: #685bde; }
+.nav-count { margin-left: auto; border-radius: 5px; background: #fff; padding: 2px 7px; color: #777b89; font-size: 10px; }
+
+.sidebar-bottom { margin-top: auto; }
+.help-card { display: flex; align-items: center; gap: 9px; border: 1px solid #eeedf5; border-radius: 10px; background: #fbfaff; padding: 12px 10px; }
+.help-icon { display: grid; width: 26px; height: 26px; flex: 0 0 auto; place-items: center; border-radius: 8px; background: #eeebff; color: #6759d9; font-size: 13px; font-weight: 700; }
+.help-card div, .user-copy { display: grid; gap: 3px; }
+.help-card strong, .user-copy strong { color: #393c48; font-size: 11px; font-weight: 600; }
+.help-card div span, .user-copy span { color: #9295a1; font-size: 10px; }
+.help-arrow { margin-left: auto; color: #999ca7; font-size: 13px; }
+.user-card { display: flex; align-items: center; gap: 10px; margin-top: 17px; border-top: 1px solid #eeeef2; padding: 16px 4px 0; }
+.avatar { display: grid; width: 32px; height: 32px; place-items: center; border-radius: 50%; background: #fae5d9; color: #9a5836; font-size: 10px; font-weight: 700; }
+.user-menu { margin-left: auto; color: #989ba6; font-size: 20px; letter-spacing: 1px; }
+
+.main-panel { min-height: 100vh; margin-left: 250px; }
+.topbar { display: flex; height: 68px; align-items: center; justify-content: space-between; border-bottom: 1px solid #eceef2; background: #fff; padding: 0 43px; }
+.breadcrumbs { display: flex; align-items: center; gap: 11px; color: #9295a0; font-size: 12px; }
+.breadcrumbs strong { color: #343743; font-weight: 600; }
+.crumb-divider { color: #c2c4cc; }
+.topbar-actions { display: flex; align-items: center; gap: 19px; }
+.icon-button { position: relative; display: grid; width: 28px; height: 30px; place-items: center; border: 0; background: transparent; color: #777b88; font-size: 21px; }
+.search-button { font-size: 26px; transform: rotate(-20deg); }
+.notification-button { font-size: 18px; }
+.notification-button span { position: absolute; top: 5px; right: 4px; width: 5px; height: 5px; border: 1px solid #fff; border-radius: 50%; background: #ed7b72; }
+.topbar-divider { height: 25px; border-left: 1px solid #e9eaf0; }
+.store-switcher { display: flex; align-items: center; gap: 9px; color: #505360; font-size: 12px; font-weight: 500; }
+.store-dot { width: 8px; height: 8px; border-radius: 3px; background: #7365e6; }
+.chevron { margin-left: 2px; color: #90939e; font-size: 15px; }
+
+.content { max-width: 1500px; margin: 0 auto; padding: 41px 43px 22px; }
+.page-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
+.eyebrow { margin-bottom: 8px; color: #8e91a0; font-size: 10px; font-weight: 700; letter-spacing: 1.1px; }
+h1, h2, p { margin: 0; }
+h1 { color: #272a35; font-family: Manrope, sans-serif; font-size: 30px; font-weight: 700; letter-spacing: -1.25px; line-height: 1.25; }
+.page-description { margin-top: 8px; color: #878b98; font-size: 12px; }
+.sync-button { display: flex; min-height: 39px; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: 7px; background: var(--purple); padding: 0 15px; box-shadow: 0 2px 4px #5548cb27; color: #fff; font-size: 11px; font-weight: 600; transition: background .15s ease, transform .15s ease; }
+.sync-button:hover { transform: translateY(-1px); background: var(--purple-dark); }
+.sync-button:focus-visible, .filter-button:focus-visible, .icon-button:focus-visible { outline: 3px solid #aaa2ff; outline-offset: 2px; }
+.sync-icon { font-size: 17px; line-height: 1; }
+.sync-note { display: flex; align-items: center; gap: 8px; margin-top: 22px; border: 1px solid #e7e4fb; border-radius: 7px; background: #f5f3ff; padding: 10px 12px; color: #69677d; font-size: 11px; }
+.note-icon { display: grid; width: 14px; height: 14px; flex: 0 0 auto; place-items: center; border: 1px solid #8276dc; border-radius: 50%; color: #6d61ce; font-size: 9px; font-weight: 700; }
+
+.stats-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 15px; margin-top: 19px; }
+.stat-card { min-height: 123px; border: 1px solid #e9eaf0; border-radius: 9px; background: #fff; padding: 15px 17px 12px; box-shadow: 0 1px 2px #171a2404; }
+.stat-top { display: flex; align-items: center; justify-content: space-between; color: #777b89; font-size: 11px; }
+.stat-icon { display: grid; width: 27px; height: 27px; place-items: center; border-radius: 8px; font-size: 14px; }
+.stat-icon.purple { background: #f0eeff; color: #6a5de1; }
+.stat-icon.green { background: #eaf8f1; color: #2caa76; }
+.stat-icon.blue { background: #eaf3ff; color: #4c90e2; }
+.stat-value { margin-top: 4px; color: #282b36; font-family: Manrope, sans-serif; font-size: 24px; font-weight: 700; letter-spacing: -.7px; }
+.stat-foot { display: flex; align-items: center; gap: 6px; margin-top: 3px; color: #9699a5; font-size: 10px; }
+.stat-dot { display: inline-block; width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; }
+.green-dot { background: #39b77c; }
+.status-value { display: flex; align-items: center; gap: 7px; margin-top: 7px; color: #333742; font-size: 15px; font-weight: 600; }
+
+.catalog-card { overflow: hidden; margin-top: 21px; border: 1px solid #e8e9ef; border-radius: 9px; background: #fff; box-shadow: 0 1px 3px #20253405; }
+.catalog-toolbar { display: flex; min-height: 82px; align-items: center; justify-content: space-between; gap: 15px; padding: 16px 19px; }
+h2 { display: flex; align-items: center; gap: 9px; color: #343742; font-size: 13px; font-weight: 600; }
+.product-count { border-radius: 5px; background: #f1f0ff; padding: 3px 7px; color: #6659d5; font-size: 9px; font-weight: 600; }
+.catalog-toolbar p { margin-top: 5px; color: #9699a4; font-size: 10px; }
+.table-actions { display: flex; align-items: center; gap: 9px; }
+.filter-search { display: flex; width: 194px; height: 33px; align-items: center; gap: 7px; border: 1px solid #e8e9ee; border-radius: 6px; padding: 0 9px; color: #9295a0; }
+.filter-search span { font-size: 20px; line-height: 1; transform: rotate(-20deg); }
+.filter-search input { width: 100%; min-width: 0; border: 0; outline: 0; background: transparent; color: #444752; font-size: 10px; }
+.filter-search input::placeholder { color: #a0a2ad; }
+.filter-button { display: flex; height: 33px; align-items: center; gap: 7px; border: 1px solid #e8e9ee; border-radius: 6px; background: #fff; padding: 0 10px; color: #626572; font-size: 10px; }
+.filter-button span:first-child { font-size: 15px; }
+.filter-chevron { margin-left: 2px; color: #999ba6; font-size: 13px; }
+.table-wrap { width: 100%; overflow-x: auto; }
+table { width: 100%; border-collapse: collapse; text-align: left; white-space: nowrap; }
+thead { background: #fafbfc; }
+th { height: 37px; border-top: 1px solid #eff0f3; border-bottom: 1px solid #eff0f3; color: #9295a1; font-size: 9px; font-weight: 600; letter-spacing: .5px; }
+td { height: 60px; border-bottom: 1px solid #f0f1f4; color: #666a77; font-size: 11px; }
+tbody tr:last-child td { border-bottom: 0; }
+th:first-child, td:first-child { padding-left: 18px; }
+th:last-child, td:last-child { padding-right: 16px; }
+.check-cell { width: 40px; }
+.check-cell input { width: 13px; height: 13px; margin: 0; accent-color: #685bdc; vertical-align: middle; }
+.product-cell { display: flex; align-items: center; gap: 11px; }
+.product-thumb { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 7px; background: #f1efff; color: #675bce; font-family: Manrope, sans-serif; font-size: 14px; font-weight: 700; }
+.thumb-1 { background: #edf6ff; color: #5282bc; }
+.thumb-2 { background: #eaf7f1; color: #39916b; }
+.thumb-3 { background: #fff2e9; color: #b27343; }
+.thumb-4 { background: #fcecf0; color: #b46079; }
+.product-copy { display: grid; gap: 4px; }
+.product-copy strong { color: #383b46; font-size: 11px; font-weight: 600; }
+.product-copy span { color: #a0a2ac; font-size: 9px; }
+.product-id { color: #858894; font-size: 10px; }
+.price { color: #444752; font-size: 11px; font-weight: 600; }
+.active-badge { display: inline-flex; align-items: center; gap: 6px; border-radius: 12px; background: #ecf8f1; padding: 5px 8px; color: #328a60; font-size: 9px; font-weight: 600; }
+.status-dot { width: 5px; height: 5px; border-radius: 50%; background: #39b77c; }
+.row-menu { border: 0; background: transparent; padding: 3px 5px; color: #9295a0; font-size: 18px; letter-spacing: 1px; line-height: 1; }
+.table-footer { display: flex; min-height: 51px; align-items: center; justify-content: space-between; border-top: 1px solid #eff0f3; padding: 0 18px; color: #9295a0; font-size: 10px; }
+.table-footer strong { color: #5b5e69; font-weight: 600; }
+.pagination { display: flex; gap: 7px; }
+.pagination button { height: 27px; border: 1px solid #e8e9ee; border-radius: 5px; background: #fff; padding: 0 9px; color: #717480; font-size: 9px; }
+.pagination button:disabled { cursor: not-allowed; color: #b6b8c1; }
+.page-footer { display: flex; justify-content: space-between; margin-top: 17px; color: #a3a5af; font-size: 9px; }
+
+@media (min-width: 1500px) {
+  .content { padding-right: 56px; padding-left: 56px; }
+}
+
+@media (max-width: 1050px) {
+  .sidebar { width: 215px; }
+  .main-panel { margin-left: 215px; }
+  .topbar { padding: 0 28px; }
+  .content { padding: 34px 28px 20px; }
+  .stats-grid { gap: 10px; }
+  .filter-search { width: 160px; }
+}
+
+@media (max-width: 760px) {
+  .sidebar { position: static; width: auto; height: auto; border-right: 0; border-bottom: 1px solid #e9eaf0; padding: 13px 16px; }
+  .workspace-label, .sidebar-bottom { display: none; }
+  .navigation { display: flex; gap: 4px; margin-top: 13px; overflow-x: auto; }
+  .nav-link { min-width: max-content; height: 35px; padding: 0 10px; }
+  .main-panel { margin-left: 0; }
+  .topbar { height: 54px; padding: 0 17px; }
+  .topbar-actions { gap: 11px; }
+  .store-switcher { font-size: 10px; }
+  .content { padding: 26px 17px 18px; }
+  .page-heading { align-items: flex-start; flex-direction: column; }
+  .sync-button { min-height: 36px; }
+  .stats-grid { grid-template-columns: 1fr; }
+  .stat-card { min-height: 106px; }
+  .catalog-toolbar { align-items: flex-start; flex-direction: column; }
+  .table-actions { width: 100%; }
+  .filter-search { flex: 1; width: auto; }
+  .table-footer { padding: 0 12px; }
+  .page-footer { gap: 8px; flex-wrap: wrap; }
+}
+
+@media (max-width: 420px) {
+  .brand { padding: 0 3px; }
+  .topbar { padding: 0 12px; }
+  .breadcrumbs { gap: 6px; font-size: 10px; }
+  .topbar-actions { gap: 5px; }
+  .store-switcher { gap: 5px; }
+  .content { padding-right: 12px; padding-left: 12px; }
+  h1 { font-size: 27px; }
+  .pagination { gap: 4px; }
+  .pagination button { padding: 0 6px; }
+}
*** End Patch
PATCH
npm run build"
